"use strict";

const easy = [
  {title:"Een woord kiezen",kind:"choice",prompt:"Waarmee kun je iemand bellen?",options:["📖 Boek","📱 Telefoon","🔑 Sleutel","☕ Kopje"],answer:1,hint:"Je houdt het vaak in je hand en hoort het rinkelen."},
  {title:"In de keuken",kind:"choice",prompt:"Waaruit drink je koffie of thee?",options:["🪑 Stoel","🔑 Sleutel","☕ Kopje","👟 Schoen"],answer:2,hint:"Je kunt het op tafel zetten."},
  {title:"Groeten",kind:"choice",prompt:"Wat zeg je meestal als je iemand ziet?",options:["Tot morgen","Hallo","Welterusten","Dank je"],answer:1,hint:"Je begint er een gesprek mee."},
  {title:"Woorden lezen",kind:"open",prompt:"Lees of wijs deze woorden aan. Zeg er één hardop als je wilt.",words:["water","huis","stoel","brood","telefoon"],hint:"Een ander kan de woorden rustig voorlezen. Aanwijzen telt ook."},
  {title:"Aanvullen",kind:"choice",prompt:"Ik slaap in een ...",options:["bed","trein","tuin","glas"],answer:0,hint:"Waar ligt een kussen?"},
  {title:"Ja of nee",kind:"choice",prompt:"Een fiets heeft meestal twee wielen.",options:["Ja","Nee"],answer:0,hint:"Denk aan een gewone fiets."},
  {title:"Tegenstellingen",kind:"choice",prompt:"Wat is het tegenovergestelde van KOUD?",options:["Warm","Blauw","Kort","Zacht"],answer:0,hint:"Hoe noem je iets dat veel warmte heeft?"},
  {title:"Wat hoort erbij?",kind:"choice",prompt:"Welk woord hoort bij 'eten'?",options:["lepel","kussen","jas","telefoon"],answer:0,hint:"Waarmee kun je soep eten?"},
  {title:"Een zin maken",kind:"open",prompt:"Maak of wijs een zin met deze woorden.",words:["Ik","wil","graag","water"],hint:"Voorbeeld: 'Ik wil graag water.' Gebaren of aanwijzen mag ook."},
  {title:"De dag",kind:"choice",prompt:"Welke dag komt na maandag?",options:["vrijdag","dinsdag","zondag","zaterdag"],answer:1,hint:"Denk aan het begin van de week."},
  {title:"Hulp vragen",kind:"choice",prompt:"Wat kun je zeggen als je ergens hulp bij wilt?",options:["Ik wil hulp","Ik ga weg","Ik ben laat","Tot morgen"],answer:0,hint:"Het begint met 'Ik wil ...'"},
  {title:"Mijn eigen woorden",kind:"open",prompt:"Noem, schrijf, teken of wijs drie dingen aan die belangrijk zijn voor jou.",words:["een persoon","een plek","iets leuks"],hint:"Neem rustig de tijd. Er is geen fout antwoord."}
];

const medium = [
  {title:"Een zin aanvullen",kind:"choice",prompt:"Morgen heb ik een afspraak. Ik zet de tijd in mijn ...",options:["agenda","schoen","pan","tuin"],answer:0,hint:"Waar schrijf je afspraken op?"},
  {title:"Een goede volgorde",kind:"choice",prompt:"Welke zin klopt het best?",options:["Ik koffie drink in de ochtend.","In ochtend ik drink koffie.","Ik drink 's ochtends koffie."],answer:2,hint:"Denk aan de volgorde: wie - doet wat - wanneer."},
  {title:"Welk woord past niet?",kind:"choice",prompt:"Drie woorden zijn kleding. Welk woord hoort er niet bij?",options:["jas","broek","fiets","trui"],answer:2,hint:"Wat kun je aantrekken?"},
  {title:"Een verband zoeken",kind:"choice",prompt:"Sleutel hoort bij deur, zoals wachtwoord hoort bij ...",options:["account","bord","fiets","bloem"],answer:0,hint:"Waarmee log je in?"},
  {title:"Een kort bericht",kind:"story",story:"Noor heeft woensdag om twee uur een afspraak bij de logopedist. Ze gaat met de bus en neemt haar agenda mee.",prompt:"Op welke dag is de afspraak?",options:["maandag","woensdag","vrijdag"],answer:1,hint:"Lees de eerste zin nog een keer."},
  {title:"Nog een vraag",kind:"story",story:"Noor heeft woensdag om twee uur een afspraak bij de logopedist. Ze gaat met de bus en neemt haar agenda mee.",prompt:"Hoe reist Noor?",options:["met de fiets","met de auto","met de bus"],answer:2,hint:"Het staat in de tweede zin."},
  {title:"Wat doe je eerst?",kind:"choice",prompt:"Je wilt een afspraak maken. Wat is een logische eerste stap?",options:["De praktijk bellen","Alvast afscheid nemen","Je jas ophangen"],answer:0,hint:"Hoe neem je contact op?"},
  {title:"De ontbrekende schakel",kind:"choice",prompt:"Ik was mijn handen met water en ...",options:["zeep","papier","zand","melk"],answer:0,hint:"Wat gebruik je om je handen schoon te maken?"},
  {title:"Betekenis",kind:"choice",prompt:"Welk woord betekent ongeveer hetzelfde als 'blij'?",options:["boos","vrolijk","moe","stil"],answer:1,hint:"Je voelt je goed en lacht misschien."},
  {title:"Informatie onthouden",kind:"story",story:"Sam neemt om half elf de trein naar Utrecht. Hij bezoekt zijn zus. Daarna gaat hij weer naar huis.",prompt:"Wie gaat Sam bezoeken?",options:["een collega","zijn zus","een buurman"],answer:1,hint:"Zoek de zin waarin 'bezoekt' staat."},
  {title:"Een gesprek oefenen",kind:"open",prompt:"Stel jezelf voor aan iemand die je nog niet kent.",words:["Mijn naam is ...","Ik woon in ...","Ik houd van ..."],hint:"Je kunt zinnen zeggen, opschrijven of één woord tegelijk aanwijzen."},
  {title:"Een verhaal vertellen",kind:"open",prompt:"Vertel, schrijf of teken wat jij graag doet op een fijne dag.",words:["Eerst ...","Daarna ...","Tot slot ..."],hint:"Er is geen goed of fout verhaal. Een begeleider kan de woorden opschrijven."}
];

const board = [
  {id:"snel",label:"Snel zeggen",items:[["✅","Ja"],["❌","Nee"],["🤔","Ik weet het niet"],["🛑","Stop alsjeblieft"],["🗣️","Praat langzamer"],["✍️","Schrijf het op"],["⏳","Geef me tijd"],["🔁","Nog een keer"],["🙋","Ik heb hulp nodig"]]},
  {id:"nodig",label:"Ik heb nodig",items:[["💧","Ik wil wat drinken"],["🚻","Ik moet naar het toilet"],["🛏️","Ik wil rusten"],["🧥","Ik heb het koud"],["☀️","Ik heb het warm"],["📱","Ik wil mijn telefoon"],["👥","Ik wil bezoek"],["🤫","Ik wil stilte"],["🧑‍⚕️","Ik wil een verpleegkundige spreken"]]},
  {id:"gevoel",label:"Hoe ik me voel",items:[["🙂","Ik voel me goed"],["😔","Ik ben verdrietig"],["😣","Ik ben moe"],["😟","Ik ben bang"],["😤","Ik ben gefrustreerd"],["😌","Ik ben rustig"],["❤️","Ik ben blij je te zien"],["😕","Ik begrijp het niet"],["💬","Ik wil praten"]]},
  {id:"lichaam",label:"Mijn lichaam",items:[["🤕","Ik heb pijn"],["🤯","Ik heb hoofdpijn"],["🌀","Ik ben duizelig"],["🤢","Ik ben misselijk"],["😮‍💨","Ik ben benauwd"],["👀","Ik zie niet goed"],["👂","Ik hoor je niet goed"],["✋","Hier doet het pijn"],["🚨","Ik voel me plotseling slechter"]]},
  {id:"mensen",label:"Mensen",items:[["👨‍👩‍👧","Mijn familie"],["🧑‍🤝‍🧑","Mijn vriend of vriendin"],["🧑‍⚕️","De arts"],["🗣️","De logopedist"],["💆","De therapeut"],["🙋","Ikzelf"],["📞","Ik wil iemand bellen"],["🏡","Ik wil naar huis"],["🤝","Blijf even bij me"]]},
  {id:"dag",label:"Mijn dag",items:[["🍽️","Eten"],["🧼","Wassen"],["👕","Aankleden"],["🚶","Wandelen"],["🪑","Zitten"],["📺","Televisie"],["🎵","Muziek"],["📖","Lezen"],["🕒","Hoe laat is het?"]]},
  {id:"vragen",label:"Vragen",items:[["❓","Wat bedoel je?"],["📅","Welke dag is het?"],["📍","Waar zijn we?"],["👥","Wie komt er?"],["⏰","Wanneer?"],["📝","Wat gaan we doen?"],["🔁","Wil je het herhalen?"],["💭","Mag ik even nadenken?"],["👍","Dat klopt"]]}
];

const state={view:"home",book:"easy",index:0,boardTab:"snel",selected:null,hint:false,phrase:"Tik op een zin hieronder",drafts:{easy:{},medium:{}},customPhrases:[],prefs:{scale:1,contrast:false}};
const main=document.getElementById("main");
const safeRead=(key)=>{try{return localStorage.getItem(key)}catch{return null}};
const safeWrite=(key,value)=>{try{localStorage.setItem(key,value)}catch{}};
const savedPrefs=safeRead("afasie-prefs");
if(savedPrefs){try{const p=JSON.parse(savedPrefs);state.prefs.scale=Math.max(.95,Math.min(1.35,Number(p.scale)||1));state.prefs.contrast=!!p.contrast}catch{}}
try{const p=JSON.parse(safeRead("afasie-eigen-woorden")||"[]");if(Array.isArray(p))state.customPhrases=p.filter(x=>typeof x==="string").map(x=>x.trim().slice(0,70)).filter(Boolean).slice(0,9)}catch{}
applyPrefs();

function applyPrefs(){document.documentElement.style.setProperty("--text-scale",state.prefs.scale);document.body.classList.toggle("high-contrast",state.prefs.contrast);document.getElementById("contrastBtn").setAttribute("aria-pressed",String(state.prefs.contrast));safeWrite("afasie-prefs",JSON.stringify(state.prefs))}
function notify(message){const el=document.getElementById("toast");el.textContent=message;el.classList.add("show");clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove("show"),3200)}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[ch])}
function speak(message){if(!("speechSynthesis" in window)){notify("Voorlezen is niet beschikbaar in deze browser.");return}try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(message);u.lang="nl-NL";u.rate=.83;u.pitch=1;speechSynthesis.speak(u)}catch{notify("Voorlezen lukte niet. Je kunt de tekst wel aanwijzen.")}}
function goHome(){state.view="home";state.selected=null;render()}
function openBook(book){state.view=book;state.book=book;state.selected=null;state.hint=false;state.index=Number(safeRead("afasie-progress-"+book))||0;state.index=Math.max(0,Math.min(state.index,(book==="easy"?easy:medium).length-1));render()}
function openBoard(){state.view="board";state.phrase="Tik op een zin hieronder";state.boardTab="snel";render()}
function render(){if(state.view==="home")main.innerHTML=homePage();else if(state.view==="board")main.innerHTML=boardPage();else main.innerHTML=exercisePage();window.scrollTo({top:0,behavior:"auto"})}
function bookCard(variant,title,desc,icon,klass,nr){return `<article class="book-card"><div class="book-visual ${klass}"><div class="book-cover" aria-hidden="true"><span class="symbol">${icon}</span><div class="lines"><i></i><i></i><i></i></div></div></div><div class="book-body"><span class="mini-info">${nr}</span><h3>${title}</h3><p>${desc}</p><button class="btn" data-action="${variant}">Open boekje <span aria-hidden="true">→</span></button></div></article>`}
function homePage(){return `
<section class="hero"><div class="hero-copy"><span class="pill">● Oefenen op jouw tempo</span><h1>Elk woord is<br><em>een stap vooruit.</em></h1><p>Rustige oefeningen voor taal en communicatie na een beroerte. Op je telefoon, tablet of computer. Praten, aanwijzen en schrijven mag allemaal.</p><div class="hero-actions"><button class="btn" data-action="easy">Begin met oefenen <span aria-hidden="true">→</span></button><button class="btn secondary" data-action="board">Open het communicatiebord</button></div></div><div class="hero-art" aria-hidden="true"><svg class="hero-svg" viewBox="0 0 440 385" xmlns="http://www.w3.org/2000/svg"><rect x="47" y="54" width="312" height="242" rx="33" fill="#fffdf9"/><path d="M74 91h257" stroke="#bdd8ca" stroke-width="3"/><circle cx="100" cy="133" r="25" fill="#f4d99c"/><path d="M90 133h20M100 123v20" stroke="#226a61" stroke-width="5" stroke-linecap="round"/><rect x="148" y="117" width="165" height="15" rx="7" fill="#bdddd0"/><rect x="148" y="144" width="128" height="13" rx="6" fill="#e3ede7"/><circle cx="100" cy="225" r="25" fill="#d5e6f4"/><path d="M87 224l9 9 18-21" fill="none" stroke="#226a61" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><rect x="148" y="209" width="157" height="15" rx="7" fill="#bdddd0"/><rect x="148" y="237" width="112" height="13" rx="6" fill="#e3ede7"/><path d="M290 279c0-33 28-60 62-60h18c33 0 60 27 60 60v37h-35l-41 33v-33h-2c-35 0-62-29-62-37Z" fill="#216b64"/><circle cx="330" cy="279" r="7" fill="white"/><circle cx="358" cy="279" r="7" fill="white"/><circle cx="386" cy="279" r="7" fill="white"/></svg></div></section>
<section class="books" id="boeken"><div class="section-head"><div><span class="pill">Kies wat bij je past</span><h2 style="margin-top:14px">Drie manieren om te oefenen</h2></div><p>Begin makkelijk of kies een uitdaging. Je kunt elke opdracht overslaan of later opnieuw doen.</p></div><div class="book-grid">${bookCard("easy","Woorden terugvinden","Herkennen, aanwijzen, nazeggen en korte zinnen.","Aa","mint","Niveau 1 · Eenvoudig")}${bookCard("medium","Zinnen en verhalen","Meer woorden, verbanden en korte teksten.","✎","blue","Niveau 2 · Uitdagender")}${bookCard("board","Ik wil iets vertellen","Direct zinnen aanwijzen, laten voorlezen en tonen.","◌","gold","Communicatiebord")}</div></section>
<section class="how-section"><span class="pill">Fijn oefenen</span><h2 style="margin-top:15px">Zo werkt het</h2><div class="how-grid"><div class="how-item"><span class="how-number">01</span><div><h3>Kies een opdracht</h3><p>Doe één pagina tegelijk. Een paar minuten is ook goed.</p></div></div><div class="how-item"><span class="how-number">02</span><div><h3>Antwoord op jouw manier</h3><p>Wijs aan, zeg het, schrijf het of maak een gebaar.</p></div></div><div class="how-item"><span class="how-number">03</span><div><h3>Neem gerust pauze</h3><p>Geen klok, geen punten, geen verplichte volgorde.</p></div></div></div></section>
<section class="downloads"><div class="section-head"><div><span class="pill">Ook op papier</span><h2 style="margin-top:14px">Printbare boekjes</h2></div><p>Open of download de PDF op je telefoon. Afdrukken op A4 kan ook.</p></div><div class="download-grid"><a class="download-link" href="pdf/01-woorden-terugvinden.pdf" target="_blank" rel="noopener">↓ Woorden terugvinden<span>PDF · Groot lettertype</span></a><a class="download-link" href="pdf/02-zinnen-en-verhalen.pdf" target="_blank" rel="noopener">↓ Zinnen en verhalen<span>PDF · Meer uitdaging</span></a><a class="download-link" href="pdf/03-ik-wil-iets-vertellen.pdf" target="_blank" rel="noopener">↓ Ik wil iets vertellen<span>PDF · Communicatiekaarten</span></a></div></section>
<section class="careful-note"><h2>Goed om te weten</h2><p>Afasie is bij iedereen anders. Deze oefeningen helpen bij het oefenen van taal en communicatie, maar zijn geen medische test en vervangen geen persoonlijke begeleiding door een logopedist. Vraag om hulp als de opdrachten niet passen. Bij nieuwe, plotselinge uitval of nieuwe spraakproblemen: bel 112.</p><p>De site bewaart het paginanummer, leesinstellingen en eventueel toegevoegde persoonlijke zinnen alleen op dit apparaat. Er worden geen oefenantwoorden naar een server verzonden. Gebruik op een gedeeld apparaat de knop om gegevens te wissen.</p><p><a href="https://www.thuisarts.nl/beroerte/omgaan-met-gevolgen-herseninfarct-of-hersenbloeding" target="_blank" rel="noopener">Informatie over afasie bij Thuisarts ↗</a> · <a href="https://www.afasie.nl/" target="_blank" rel="noopener">Afasie.nl ↗</a></p></section>`}
function exercisePage(){
  const items=state.book==="easy"?easy:medium;
  const ex=items[state.index];
  const isOpen=ex.kind==="open";
  const optionHtml=(ex.options||[]).map((v,i)=>`<button type="button" class="choice ${state.selected===i?'selected':''}" data-choice="${i}" aria-pressed="${state.selected===i}">${v}</button>`).join("");
  const story=ex.story?`<div class="reading-box">${ex.story}</div>`:"";
  const words=ex.words?`<div class="word-cloud">${ex.words.map(w=>`<span class="word-chip">${w}</span>`).join("")}</div>`:"";
  const indexMenu=items.map((item,i)=>`<button class="lesson-jump ${i===state.index?'current':''}" data-jump="${i}" ${i===state.index?'aria-current="step"':''}>${i+1}. ${item.title}</button>`).join("");
  return `<div class="activity-shell">
    <div class="breadcrumb"><button data-action="home">Start</button> <span aria-hidden="true">/</span> ${state.book==="easy"?"Woorden terugvinden":"Zinnen en verhalen"}</div>
    <div class="activity-header"><span class="pill">${state.book==="easy"?"Niveau 1":"Niveau 2"}</span><span class="lesson-count">Opdracht ${state.index+1} van ${items.length}</span></div>
    <div class="progress" role="progressbar" aria-label="Voortgang in het boekje" aria-valuemin="0" aria-valuemax="${items.length}" aria-valuenow="${state.index+1}"><div style="width:${(state.index+1)/items.length*100}%"></div></div>
    <article class="exercise-card"><span class="mini-info">${isOpen?"Praten · schrijven · aanwijzen":"Kies een antwoord"}</span><h2>${ex.title}</h2>${story}<p class="exercise-prompt">${ex.prompt}</p>${words}
    ${isOpen?`<textarea class="answer-field" aria-label="Schrijf hier als je wilt" placeholder="Schrijven mag, maar hoeft niet.">${escapeHtml(state.drafts[state.book][state.index]||"")}</textarea>`:`<div class="choice-grid">${optionHtml}</div>`}
    <div class="feedback" role="status" aria-live="polite">${state.selected!==null?"Je hebt iets gekozen. Bekijk gerust het voorbeeldantwoord of ga verder.":""}</div>
    <div class="exercise-actions"><button class="btn secondary" data-action="hint">${state.hint?"Verberg hint":"Ik wil een hint"}</button><button class="btn secondary" data-action="answer">Voorbeeldantwoord</button><button class="btn secondary" data-action="read">🔊 Lees voor</button></div>
    ${state.hint?`<p class="hint">💡 ${ex.hint}</p>`:""}<div id="answerArea" class="visually-hidden" role="status" aria-live="polite"></div></article>
    <div class="activity-nav"><button class="btn secondary" data-action="prev" ${state.index===0?'disabled':''}>← Vorige</button><button class="btn" data-action="next">${state.index===items.length-1?'Terug naar start':'Volgende →'}</button></div>
    <details class="lesson-index"><summary>Andere opdracht kiezen</summary><div class="lesson-list">${indexMenu}</div><button class="text-link" data-action="restart-book">Ga terug naar opdracht 1</button></details>
    <aside class="notes-panel"><b>Voor wie helpt:</b> Stel één vraag tegelijk. Geef rustig tijd. Aanwijzen, tekenen of schrijven is ook goed. Corrigeer niet voortdurend.</aside>
  </div>`;
}
function boardPage(){
  const cat=board.find(x=>x.id===state.boardTab);
  const isPersonal=state.boardTab==="mijn";
  const tabs=[...board,{id:"mijn",label:"Mijn woorden"}];
  const personalCards=state.customPhrases.map((phrase,i)=>`<div class="personal-tile"><button type="button" class="board-tile ${state.phrase===phrase?'selected':''}" data-custom-index="${i}" aria-label="${escapeHtml(phrase)}"><span class="emoji" aria-hidden="true">💬</span><span>${escapeHtml(phrase)}</span></button><button type="button" class="remove-phrase" data-remove-custom="${i}" aria-label="Verwijder ${escapeHtml(phrase)}">Verwijder</button></div>`).join("");
  const categories=isPersonal?`<div class="personal-editor"><h2>Mijn eigen woorden</h2><p>Maak maximaal 9 eigen zinnen voor dit communicatiebord. Ze blijven alleen op dit apparaat staan.</p><form id="personalForm"><label for="personalPhrase">Een woord of korte zin</label><div class="personal-form-row"><input id="personalPhrase" name="personalPhrase" type="text" maxlength="70" placeholder="Bijvoorbeeld: Ik wil mijn bril" required><button type="submit" class="btn" ${state.customPhrases.length>=9?'disabled':''}>Toevoegen</button></div></form>${state.customPhrases.length===0?'<p class="hint">Er staan nog geen eigen zinnen in dit bord.</p>':''}<div class="board-grid personal-grid">${personalCards}</div></div>`:`<div class="board-grid">${cat.items.map(([emoji,phrase])=>`<button class="board-tile ${state.phrase===phrase?'selected':''}" data-phrase="${escapeHtml(phrase)}" aria-label="${escapeHtml(phrase)}"><span class="emoji" aria-hidden="true">${emoji}</span><span>${escapeHtml(phrase)}</span></button>`).join("")}</div>`;
  return `<div class="activity-shell">
    <div class="breadcrumb"><button data-action="home">Start</button> <span aria-hidden="true">/</span> Communicatiebord</div>
    <div class="board-header"><span class="pill">Aanwijzen mag</span><h1 style="font-size:clamp(2.4rem,6vw,4rem);margin:16px 0">Ik wil iets vertellen</h1><p class="exercise-prompt">Kies een onderwerp en tik op een zin. Je kunt de tekst groot tonen en laten uitspreken.</p></div>
    <div class="board-phrase" role="status" aria-live="polite"><p class="caption">Dit wil ik zeggen</p><p class="spoken" id="spokenText">${escapeHtml(state.phrase)}</p><button class="btn" data-action="speak-phrase">🔊 Spreek uit</button><button class="btn secondary" data-action="clear-phrase">Wissen</button></div>
    <div class="board-tabs" role="group" aria-label="Onderwerpen">${tabs.map(x=>`<button class="board-tab ${x.id===state.boardTab?'active':''}" data-boardtab="${x.id}" aria-pressed="${x.id===state.boardTab}">${x.label}</button>`).join("")}</div>
    ${categories}
    <p class="board-disclaimer"><b>Let op:</b> Bij nieuwe, plotselinge klachten zoals nieuwe spraakuitval, een scheve mond of verlamming: meteen medische hulp inschakelen (in Nederland 112). Voor gewone klachten: waarschuw de zorgverlener. Dit bord vervangt geen noodoproep.</p>
  </div>`;
}
document.querySelector("#homeBtn").addEventListener("click",goHome);
document.querySelector("#smallerText").addEventListener("click",()=>{state.prefs.scale=Math.max(.95,Math.round((state.prefs.scale-.1)*100)/100);applyPrefs();notify("Tekstgrootte aangepast")});
document.querySelector("#biggerText").addEventListener("click",()=>{state.prefs.scale=Math.min(1.35,Math.round((state.prefs.scale+.1)*100)/100);applyPrefs();notify("Tekstgrootte aangepast")});
document.querySelector("#contrastBtn").addEventListener("click",()=>{state.prefs.contrast=!state.prefs.contrast;applyPrefs()});
document.querySelector("#resetBtn").addEventListener("click",()=>{if(!confirm("Wil je de voortgang, leesinstellingen en eventueel toegevoegde eigen zinnen op dit apparaat wissen?"))return;try{for(const k of ["afasie-prefs","afasie-progress-easy","afasie-progress-medium","afasie-eigen-woorden"])localStorage.removeItem(k)}catch{}state.prefs={scale:1,contrast:false};state.customPhrases=[];state.drafts={easy:{},medium:{}};state.index=0;applyPrefs();notify("Gegevens op dit apparaat gewist.");goHome()});
main.addEventListener("input",event=>{if(event.target.matches(".answer-field")&&(state.book==="easy"||state.book==="medium")){state.drafts[state.book][state.index]=event.target.value}});
main.addEventListener("submit",event=>{if(event.target.id!=="personalForm")return;event.preventDefault();const input=event.target.querySelector("#personalPhrase");const phrase=input.value.trim().slice(0,70);if(!phrase){notify("Vul eerst een woord of zin in.");return}if(state.customPhrases.length>=9){notify("Je kunt maximaal 9 eigen zinnen toevoegen.");return}if(state.customPhrases.some(x=>x.toLowerCase()===phrase.toLowerCase())){notify("Deze zin staat er al in.");return}state.customPhrases.push(phrase);safeWrite("afasie-eigen-woorden",JSON.stringify(state.customPhrases));state.phrase=phrase;render();notify("Je eigen zin is toegevoegd.")});
main.addEventListener("click",event=>{const target=event.target.closest("button");if(!target)return;
 const action=target.dataset.action;
 if(action==="home")return goHome();
 if(action==="easy"||action==="medium")return openBook(action);
 if(action==="board")return openBoard();
 if(action==="prev"||action==="next"){const items=state.book==="easy"?easy:medium;if(action==="next"&&state.index===items.length-1){safeWrite("afasie-progress-"+state.book,"0");return goHome()}state.index=Math.max(0,Math.min(items.length-1,state.index+(action==="next"?1:-1)));state.selected=null;state.hint=false;safeWrite("afasie-progress-"+state.book,String(state.index));render();return;}
 if(target.dataset.jump!==undefined||action==="restart-book"){const items=state.book==="easy"?easy:medium;const next=action==="restart-book"?0:Number(target.dataset.jump);if(!Number.isInteger(next)||next<0||next>=items.length)return;state.index=next;state.selected=null;state.hint=false;safeWrite("afasie-progress-"+state.book,String(next));render();return;}
 if(target.dataset.choice!==undefined){state.selected=Number(target.dataset.choice);document.querySelectorAll(".choice").forEach(button=>{const active=Number(button.dataset.choice)===state.selected;button.classList.toggle("selected",active);button.setAttribute("aria-pressed",String(active))});const feedback=document.querySelector(".exercise-card .feedback");if(feedback)feedback.textContent="Je hebt iets gekozen. Bekijk gerust het voorbeeldantwoord of ga verder.";return;}
 if(action==="hint"){state.hint=!state.hint;render();return;}
 if(action==="answer"){const items=state.book==="easy"?easy:medium;const ex=items[state.index];const answer=ex.answer===undefined?"Er is geen vast antwoord op deze opdracht.":ex.options[ex.answer];const el=document.getElementById("answerArea");el.classList.remove("visually-hidden");el.className="feedback";el.textContent="Voorbeeld: "+answer;return;}
 if(action==="read"){const ex=(state.book==="easy"?easy:medium)[state.index];speak((ex.story?ex.story+". ":"")+ex.prompt);return;}
 if(target.dataset.boardtab){state.boardTab=target.dataset.boardtab;render();return;}
 if(target.dataset.customIndex!==undefined){const phrase=state.customPhrases[Number(target.dataset.customIndex)];if(!phrase)return;state.phrase=phrase;document.getElementById("spokenText").textContent=phrase;document.querySelectorAll(".board-tile").forEach(x=>x.classList.toggle("selected",x.dataset.customIndex===target.dataset.customIndex));return;}
 if(target.dataset.removeCustom!==undefined){const i=Number(target.dataset.removeCustom);if(!Number.isInteger(i)||i<0||i>=state.customPhrases.length)return;const [removed]=state.customPhrases.splice(i,1);safeWrite("afasie-eigen-woorden",JSON.stringify(state.customPhrases));if(state.phrase===removed)state.phrase="Tik op een zin hieronder";render();notify("Zin verwijderd van dit apparaat.");return;}
 if(target.dataset.phrase){state.phrase=target.dataset.phrase;const t=document.getElementById("spokenText");t.textContent=state.phrase;document.querySelectorAll(".board-tile").forEach(x=>x.classList.toggle("selected",x.dataset.phrase===state.phrase));return;}
 if(action==="speak-phrase"){if(state.phrase!=="Tik op een zin hieronder")speak(state.phrase);else notify("Kies eerst een zin.");return;}
 if(action==="clear-phrase"){state.phrase="Tik op een zin hieronder";document.getElementById("spokenText").textContent=state.phrase;document.querySelectorAll(".board-tile").forEach(x=>x.classList.remove("selected"));return;}
});
render();
